import {themes,templates,artNames,sounds,collections,seedCards,seedAlbums,today,uid,newCard,newAlbum} from './data.js';
import {SoundPlayer} from './audio.js';
import {cardErrors,cardFieldLabels} from './card-validation.js';
import {motionIntent,beforeRender,afterRender,animateDialog,installMotion} from './motion.js';
import {giftPreviewMarkup,mountGiftPreview} from './gift-preview.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const KEY='journey-create-demo-v1';
const clone=o=>structuredClone(o), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY))}catch{return null}};
const db=read()||{cards:clone(seedCards),albums:clone(seedAlbums),drafts:[],giftDrafts:[],wishlist:[],snapshots:{}};
db.albumDrafts ||= [];
db.customThemes ||= [];
db.customSubthemes ||= {};
let giftCinema=null;
let card=db.currentCard||newCard(),album=db.currentAlbum||newAlbum(),gift=db.currentGift||{recipient:'',occasion:'Birthday',kind:'',items:[],speaker:0,color:'Paper white',engraving:'',collection:null};
let ui={theme:0,template:0,photoFor:'card',photoReturn:'editor',soundFor:'card',soundReturn:'editor',libraryType:'card',libraryStatus:'completed',artistCategory:'All',soundCategory:'All',collectionCategory:'All',search:'',soundSearch:'',pickSound:null,soundExpanded:false,collection:0,speaker:0,selected:[],selectionType:'card',detail:null,detailOrigin:'library',shareMode:'share',shareReturn:'detail',recordStage:'permission',recordPaused:false,recordSeconds:0,recordBlob:null,flipped:false,physical:false,writingStep:0,hardwareConnected:false,hardwareCard:false,order:'',orderReturn:'detail',error:'',mixSaved:false};
try{ui={...ui,...JSON.parse(sessionStorage.getItem(KEY+'-view')||'{}')}}catch{}
function rememberUI(){try{sessionStorage.setItem(KEY+'-view',JSON.stringify(ui))}catch{}}
let trail=[],route=(location.hash.slice(2).split('?')[0]||'home'),toastTimer,recordTimer,recorder,recordStream,chunks=[],recStarted=0,activeGeneration=null;
const player=new SoundPlayer(updatePlayer);
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const icons=()=>window.lucide?.createIcons({attrs:{'aria-hidden':'true'}});
const attr=o=>Object.entries(o||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ');
const ib=(i,label,action,data={})=>`<button type="button" class="icon-button" aria-label="${esc(label)}" data-action="${action}" ${attr(data)}>${icon(i)}</button>`;
const primary=(label,action,disabled=false)=>`<button type="button" class="primary" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
const textButton=(label,action)=>`<button type="button" class="text-button" data-action="${action}">${label}</button>`;
const secondary=(label,action)=>`<button type="button" class="secondary-button" data-action="${action}">${label}</button>`;
const row=(title,sub,action,data={},disabled=false)=>`<button type="button" class="option-row" data-action="${action}" ${attr(data)} ${disabled?'disabled':''}><span><strong>${esc(title)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span>${icon('chevron-right')}</button>`;
const field=(label,name,value,type='text',required=false)=>`<label class="field"><span>${esc(label)}${required?' <span aria-hidden="true">*</span>':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} autocomplete="off"></label>`;
const textarea=(label,name,value,required=false)=>`<label class="field"><span>${label}${required?' *':''}</span><textarea name="${name}" rows="3" ${required?'required':''}>${esc(value)}</textarea></label>`;
const heading=(title,subtitle='')=>`<header class="page-heading"><h1 class="${title.length>40?'long-title':''}" tabindex="-1">${esc(title)}</h1>${subtitle?`<p class="subtitle">${esc(subtitle)}</p>`:''}</header>`;
const top=(back=true,action='')=>`<div class="topbar">${back?ib('arrow-left','Back','back'):'<span></span>'}${action}</div>`;
const nav=current=>`<nav class="bottom-nav" aria-label="Main navigation">${[['home','house','Home'],['practice','person-standing','Practice'],['create','square-pen','Create'],['share-hub','share-2','Share']].map(([id,i,t])=>`<button data-go="${id}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;
const shell=(body,{title='',subtitle='',back=true,topAction='',footer='',navigation='',className=''}={})=>`<div class="view"><div class="content ${className}">${top(back,topAction)}${title?heading(title,subtitle):''}${ui.error?`<p class="inline-error" role="alert">${esc(ui.error)}</p>`:''}${body}</div>${footer?`<div class="sticky-actions">${footer}</div>`:''}${navigation?nav(navigation):''}</div>`;
const art=(object,extra='')=>{let p=object?.photo||`art:${object?.art||0}`;return p.startsWith('data:')||p.startsWith('blob:')?`<div class="art ${extra}"><img src="${esc(p)}" alt="${esc(object?.name||'Selected photo')}" style="object-position:${object?.cropX||50}% ${object?.cropY||50}%"></div>`:`<div class="art art-${(parseInt(p.split(':')[1])||0)%4} ${extra}" role="img" aria-label="${esc(artNames[object?.art||0]||'Paper Zen study')}"></div>`};
const paperCard=(c,{large=false,qr=false}={})=>`<div class="paper-card ${large?'paper-card-large':''} template-${c.template||0} ${ui.flipped?'is-back':''}">${ui.flipped?`<div class="card-back"><p>${esc(c.words||'A moment I want to keep.')}</p><small>${esc(c.date||today())}</small></div>`:art(c)}<div class="card-print"><span>${esc(c.name||templates[c.template||0].title)}</span><small>${c.type==='album'?'ALBUM':'JOURNEY IN ME'}</small></div>${qr?'<span class="qr-target" aria-label="QR code for this demo"></span>':''}</div>`;
const mediaPlayer=({mini=false,replay=false}={})=>`<div class="media-player ${mini?'mini-player':''}"><input aria-label="Playback progress" data-audio-progress type="range" min="0" max="${player.duration}" value="${player.current}" step="1"><div class="player-times"><span data-current>${time(player.current)}</span><span data-duration>${time(player.duration)}</span></div><div class="player-controls">${ib(replay?'rotate-ccw':'rewind',replay?'Replay':'Go back 15 seconds',replay?'replay':'rewind')}<button class="play-button" data-action="play" aria-label="${player.playing?'Pause':'Play'}">${icon(player.playing?'pause':'play')}</button>${ib('fast-forward','Go forward 15 seconds','forward')}</div></div>`;
function time(n){n=Math.max(0,Math.floor(n||0));return Math.floor(n/60).toString().padStart(2,'0')+':'+(n%60).toString().padStart(2,'0')}
function notify(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
function persist(){if((card.status==='draft'||card.editId)&&(card.name||card.words||card.photo)){db.drafts=db.drafts.filter(d=>d.id!==card.id);db.drafts.unshift(clone({...card,status:'draft'}));}if(album.status==='draft' && album.name?.trim()){db.albumDrafts=db.albumDrafts.filter(a=>a.id!==album.id);db.albumDrafts.unshift(clone(album));}try{localStorage.setItem(KEY,JSON.stringify({...db,currentCard:card,currentAlbum:album,currentGift:gift}));return true}catch{notify('Storage is full. Your current work is kept on this page.');return false}}
function saveDraft(){if(card.name||card.words||card.photo){const d={...card,status:'draft'};db.drafts=db.drafts.filter(x=>x.id!==d.id);db.drafts.unshift(d);}persist()}
function go(next,{remember=true,stop=true}={}){if(route==='gift-preview'&&next!==route){giftCinema?.destroy();giftCinema=null;}if(stop)player.pause();if(route==='recording'&&recorder&&recorder.state!=='inactive'){recorder.stop();stopRecordingTracks();}if(remember&&route!==next)trail.push(route);ui.error='';route=next;if(location.hash!=='#/'+next)location.hash='/'+next;render()}
function back(){ui.error='';motionIntent('back',true);if(route==='gift-preview'){go('gift-summary',{remember:false});return;}if(route==='memory'||route==='library'||route==='explore'||route==='gift'){go('create',{remember:false});return;}if(route==='subtheme'){go('memory',{remember:false});return;}if(route==='template'){go(ui.templateReturn||'editor',{remember:false});return;}if(route==='photo'){go(ui.photoReturn||'editor',{remember:false});return;}if(route==='artist'||route==='photos'){go('photo',{remember:false});return;}if(route==='crop'){go(ui.cropReturn||'photo',{remember:false});return;}if(route==='mixer'){go('sound',{remember:false});return;}if(route==='gift-types'){go('gift',{remember:false});return;}if(['gift-summary','gift-speaker','gift-card-choice'].includes(route)){go('gift-types',{remember:false});return;}if(route==='gift-picker'){go('gift-card-choice',{remember:false});return;}if(route==='gift-drafts'){go('gift',{remember:false});return;}if(route==='detail'&&ui.parentDetail){const p=ui.parentDetail;ui.detail=p.item;ui.detailOrigin=p.origin;ui.parentDetail=null;go(p.route,{remember:false});return;}if(route==='recording'){stopRecordingTracks();go('sound',{remember:false});return;}if(route==='sound-library'){ui.pickSound=null;ui.soundExpanded=false;go('sound',{remember:false});return;}if(route==='sound'){go(ui.soundReturn,{remember:false});return;}if(route==='share'||route==='export'){go(ui.shareReturn,{remember:false});return;}if(route==='detail'&&card.source==='album'&&ui.detail?.id===card.id){go('album-cards',{remember:false});return;}if(route==='editor'){saveDraft();go(card.source==='album'?'album-cards':card.source==='gift'?(gift.kind==='set'?'gift-summary':'gift-card-choice'):card.source==='memory'?'template':'create',{remember:false});return;}go(trail.pop()||'create',{remember:false})}
function beginCard(source,topic='',subtopic=''){card=newCard(source,topic,subtopic);ui.templateReturn=source==='memory'?'subtheme':'editor';ui.replaceGiftCard=null;ui.parentDetail=null;ui.template=0;ui.templateFor='card';if(source==='gift')card.words=`Dear ${gift.recipient}, `;ui.flipped=false;ui.photoFor='card';ui.soundFor='card';saveDraft();go(source==='memory'?'template':'editor')}
function getCreation(id){return db.cards.find(c=>c.id===id)||db.albums.find(c=>c.id===id)||db.snapshots[id]||seedCards.find(c=>c.id===id)||seedAlbums.find(c=>c.id===id)}
function currentItem(){return ui.detail||getCreation(card.id)||card}
function openDetail(item,origin='library'){ui.detail=clone(item);ui.detailOrigin=origin;ui.physical=false;ui.flipped=false;const track=item.type==='album'&&item.intro&&typeof item.intro==='object'?item.intro:item;player.configure({voice:track.recording,limit:track.recordingDuration||null,voiceVolume:track.voiceVolume,soundVolume:track.soundVolume,background:item.type==='album'&&track.recording&&!track.sound?false:true});go(item.type==='album'?'album-detail':'detail')}
function soundState(){return ui.soundFor==='intro'?(album.introDraft||(album.introDraft={recording:null,sound:null,mixed:false,voiceVolume:75,soundVolume:30})):card}
function configureSound(){const s=soundState();player.configure({voice:s.recording,limit:s.recordingDuration||(s.recording==='demo'?30:null),background:!!s.sound,voiceVolume:s.voiceVolume??75,soundVolume:s.soundVolume??30})}
function creationGrid(items,{columns=4,multi=false,selected=[],action='open-detail',date=false,creator=false,reorder=false}={}){return `<div class="creation-grid columns-${columns}">${items.map((c,i)=>`<div class="grid-cell ${multi&&selected.includes(c.id)?'selected':''}" ${reorder?`draggable="true" data-drag-id="${esc(c.id)}"`:''}><button class="grid-creation" data-action="${action}" data-id="${esc(c.id)}" ${multi?`aria-pressed="${selected.includes(c.id)}"`:''} aria-label="${esc((multi?'Select ':'Open ')+c.name)}">${art(c)}${multi?`<span class="selection-check">${selected.includes(c.id)?icon('check'):''}</span>`:''}${reorder?`<span class="order-number">${i+1}</span>`:''}<strong>${esc(c.name)}</strong>${date?`<small>${esc(c.date)}</small>`:''}${creator?`<small>${esc(c.creator||'You')}</small>`:''}</button>${reorder?`<div class="reorder-actions">${ib('ellipsis','Arrange '+c.name,'arrange-card-menu',{id:c.id})}</div>`:''}</div>`).join('')}</div>`}
function templateView(){let t=templates[ui.template];return shell(`<div class="template-carousel" data-swipe="template">${ib('chevron-left','Previous template','prev-template')}<div class="template-paper">${paperCard({name:t.title,photo:`art:${ui.template}`,template:ui.template},{large:true})}</div>${ib('chevron-right','Next template','next-template')}</div><div class="carousel-dots">${templates.map((_,i)=>`<button class="dot ${i===ui.template?'selected':''}" data-action="set-template" data-index="${i}" aria-label="Template ${i+1}" aria-pressed="${i===ui.template}"></button>`).join('')}</div><div class="template-caption"><h2>${t.title}</h2><p>${t.description}</p></div>`,{title:'Choose a template',footer:primary('Use this template','use-template')})}
function editorField(key,body){return `<div class="card-field" data-card-field="${key}">${body}<p class="card-field-error" id="card-${key}-error" hidden></p></div>`}
function editorView(){
 const editing=!!card.editId;ui.error='';
 return shell(`<div class="editor-mini-preview">${paperCard(card)}${textButton('Change template','change-template')}</div><form id="card-form" novalidate>${editorField('name',field('Card name','card.name',card.name,'text',true))}${editorField('photo',row('Photo *',card.photo?'Image selected · Change':'Choose a background or photo','card-photo'))}${editorField('words',textarea('Words to write down','card.words',card.words,true))}${field('Date','card.date',card.date,'date')}${editorField('sound',row('Sound of The Moment *',card.mixed?'Voice and sound are ready':'Recording + background sound','card-sound'))}<p class="draft-status">${icon('check')} Draft saved on this device</p></form>`,{title:editing?'Edit your card':'Create your card',footer:`<p id="card-validation-summary" class="card-validation-summary" role="alert" hidden></p><button type="submit" form="card-form" class="primary">${editing?'Save changes':'Create my cards'}</button>`});
}
function syncCardValidation(){
 const form=app.querySelector('#card-form');if(!form)return;
 const errors=ui.cardValidationFor===card.id?cardErrors(card):{};
 for(const key of Object.keys(cardFieldLabels)){
  const group=form.querySelector(`[data-card-field="${key}"]`),control=group.querySelector('input,textarea,button'),message=group.querySelector('.card-field-error');
  group.classList.toggle('has-error',!!errors[key]);
  if(errors[key]){control.setAttribute('aria-invalid','true');control.setAttribute('aria-describedby',message.id)}else{control.removeAttribute('aria-invalid');control.removeAttribute('aria-describedby')}
  message.textContent=errors[key]||'';message.hidden=!errors[key];
 }
 const summary=app.querySelector('#card-validation-summary'),missing=Object.keys(errors);
 const text=missing.length?'Please complete: '+missing.map(key=>cardFieldLabels[key]).join(' · ')+'.':'';
 if(summary.textContent!==text)summary.textContent=text;summary.hidden=!missing.length;
}
function focusFirstCardError(errors){
 const group=app.querySelector(`[data-card-field="${Object.keys(errors)[0]}"]`),content=app.querySelector('.content');
 if(!group||!content)return;
 group.querySelector('input,textarea,button')?.focus({preventScroll:true});
 requestAnimationFrame(()=>{if(route!=='editor'||!group.isConnected)return;content.scrollTo({top:content.scrollTop+group.getBoundingClientRect().top-content.getBoundingClientRect().top-28,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});
}

function soundView(){const s=soundState(),intro=ui.soundFor==='intro';return shell(`<div class="sound-steps">${row(intro?'Record an intro':'1 Add a recording',s.recording?'Recording added · Edit':'Record your voice','record-start')}${row(intro?'Choose a sound':'2 Add a Sound',s.sound?sounds.find(a=>a.id===s.sound)?.name:'Choose background sound','sound-library',{},!intro&&!s.recording)}${row(intro?'Mixer · optional':'3 Mixer',s.mixed?'Mix saved · Edit':'Mix voice and sound','mixer',{},!(s.recording&&s.sound))}</div>${intro?`<p class="subtitle">Recording or sound is enough.</p>${textButton('Remove intro sound','remove-intro')}`:''}`,{title:intro?'Album intro sound':'Sound of The Moment',footer:primary(intro?'Use intro sound':'Done','sound-done',intro?!(s.recording||s.sound):!s.mixed)})}
function recordingTitle(){return ui.soundFor==='intro'?'Record an album intro':card.source==='memory'?'Record a memory':card.source==='gift'?'Record the words that you want to tell your friend':'Record anything'}
function recordingView(){const subtitle=ui.soundFor==='intro'?album.name:card.source==='memory'?`${card.topic} · ${card.subtopic}`:'';let content,footer='';if(ui.recordStage==='permission')content=`<div class="record-permission">${icon('mic')}<h2>Your voice, kept close.</h2><p>Allow microphone access to record. Your recording stays on this device.</p>${primary('Allow microphone','allow-mic')}${textButton('Try with a demo recording','demo-recording')}</div>`;else if(ui.recordStage==='recording')content=`<div class="recording-space"><div class="waveform recording ${ui.recordPaused?'paused':''}">${Array.from({length:35},(_,i)=>`<span style="height:${10+Math.sin(i*2.5)*14+(i%4)*11}px"></span>`).join('')}</div><div class="record-time" id="record-time">${time(ui.recordSeconds)}</div><div class="record-controls">${ib(ui.recordPaused?'play':'pause',ui.recordPaused?'Resume recording':'Pause recording','record-pause')}<button class="record-stop" data-action="record-stop" aria-label="Stop recording">${icon('square')}</button></div>${textButton('Cancel','record-cancel')}</div>`;else{content=`<div class="recording-space"><div class="waveform">${Array.from({length:35},(_,i)=>`<span style="height:${12+(i*17)%47}px"></span>`).join('')}</div>${mediaPlayer({replay:true})}<div class="row center">${ib('mic','Record again','record-again')}<span class="meta">Record again</span></div></div>`;footer=primary('Use recording','use-recording')}return shell(content,{title:recordingTitle(),subtitle,footer})}
function soundLibraryView(){const q=ui.soundSearch.toLowerCase();const filtered=sounds.filter(s=>(ui.soundCategory==='All'||s.category===ui.soundCategory)&&s.name.toLowerCase().includes(q));const selected=sounds.find(s=>s.id===ui.pickSound);const mini=selected?`<section class="sound-tray ${ui.soundExpanded?'expanded':''}" aria-label="Sound preview"><button class="tray-handle" data-action="expand-sound" aria-label="${ui.soundExpanded?'Collapse':'Expand'} sound preview"><span></span></button><div class="row between"><div><h2>${selected.name}</h2><p class="meta">Paper Zen · demo audio</p></div>${ib('x','Close sound preview','close-sound')}</div>${ui.soundExpanded?art({art:selected.art}):''}${mediaPlayer({mini:!ui.soundExpanded,replay:true})}${primary('Use this sound','use-sound')}</section>`:'';return shell(`<label class="search-field">${icon('search')}<input placeholder="Search sounds" aria-label="Search sounds" name="sound-search" value="${esc(ui.soundSearch)}"></label><div class="chip-tabs" aria-label="Sound categories">${['All','Nature','Healing','Classic','Ambient','Meditation'].map(c=>`<button class="${ui.soundCategory===c?'active':''}" data-action="sound-category" data-value="${c}">${c}</button>`).join('')}</div><div class="sound-grid">${filtered.map(s=>`<button class="sound-tile ${ui.pickSound===s.id?'selected':''}" data-action="preview-sound" data-id="${s.id}" aria-label="Preview ${s.name}">${art(s)}<strong>${s.name}</strong><small>12:00</small></button>`).join('')}</div>${!filtered.length?'<p class="empty">No sounds found. Try another name.</p>':''}<div style="height:${selected?'280':'10'}px"></div>${mini}`,{title:'Sound library',className:'sound-library'})}
function mixerView(){const s=soundState();return shell(`<div class="mix-track"><div class="row">${icon('mic')}<span><strong>Recording</strong><small>Your voice</small></span>${ib('rotate-ccw','Change recording','record-start')}</div><label class="range-label">Voice volume <output>${s.voiceVolume??75}%</output><input type="range" min="0" max="100" name="voice-volume" value="${s.voiceVolume??75}"></label></div><div class="mix-track"><div class="row">${icon('music-2')}<span><strong>Background sound</strong><small>${esc(sounds.find(a=>a.id===s.sound)?.name||'Forest rain')}</small></span>${ib('list-music','Change background sound','sound-library')}</div><label class="range-label">Background volume <output>${s.soundVolume??30}%</output><input type="range" min="0" max="100" name="sound-volume" value="${s.soundVolume??30}"></label></div>${mediaPlayer()}<p class="meta center">Listen, adjust, and make it yours.</p>`,{title:'Mixer',footer:primary('Save as the sound','save-mix')})}
function libraryView({selection=false}={}){const type=selection?ui.selectionType:ui.libraryType;const items=type==='album'?(ui.libraryStatus==='drafts'&&!selection?db.albumDrafts:db.albums):(ui.libraryStatus==='drafts'&&!selection?db.drafts:db.cards);return shell(`<div class="major-tabs" role="tablist" aria-label="Creation type">${['card','album'].map(t=>`<button role="tab" tabindex="${type===t?0:-1}" aria-selected="${type===t}" class="${type===t?'active':''}" data-action="${selection?'selection-type':'library-type'}" data-value="${t}">${t==='card'?'Simple Card':'Album'}</button>`).join('')}</div>${selection?'':`<div class="minor-tabs">${['completed','drafts'].map(t=>`<button aria-pressed="${ui.libraryStatus===t}" class="${ui.libraryStatus===t?'active':''}" data-action="library-status" data-value="${t}">${t==='completed'?'Completed':'Drafts'}</button>`).join('')}</div>`}${selection?`<p class="meta space-bottom">Choose one or more creations for ${esc(gift.recipient)}. ${ui.selected.length} selected.</p>`:''}${activeGeneration&&!selection?'<p class="saved-banner">Creating your card… It will appear here when ready.</p>':''}${items.length?creationGrid(items,{columns:type==='album'?2:4,multi:selection,selected:ui.selected,action:selection?'gift-select':ui.libraryStatus==='drafts'?'resume-draft':'open-detail',date:true}):`<div class="empty">${primary('Create a Card','new-simple')}</div>`}`,{title:'My Creativity',topAction:selection?'':ib('plus','Create a card','new-simple'),footer:selection?primary(`Confirm${ui.selected.length?' · '+ui.selected.length:''}`,'confirm-gift-items',!ui.selected.length):'',navigation:selection?'':'create'})}
function detailView(){const c=currentItem(),isGift=ui.detailOrigin==='gift',isNewAlbum=ui.detailOrigin==='album-new',explore=(ui.detailOrigin==='explore'||ui.detailOrigin==='shared');return shell(`<button class="detail-card" data-action="flip-card" aria-label="Flip card">${paperCard(c,{large:true})}</button><p class="meta center">Tap card to flip</p>${mediaPlayer()}${isNewAlbum?`<p class="meta center space-top">Saved to My Creativity</p>`:''}`,{title:isNewAlbum?'Your card is ready':c.name,className:'detail-view',footer:isNewAlbum?primary('Back to Album creation','back-to-album'):isGift?primary('Share with my friend','share-gift')+detailToolbar(c,true):explore?detailToolbar(c,false,true):primary('Edit card','edit-card')+detailToolbar(c),topAction:''})}
function detailToolbar(c,giftMode=false,readOnly=false){return `<div class="detail-toolbar">${!giftMode?`<button data-action="share">${icon('share-2')}<span>Share</span></button>`:''}${!readOnly?`<button data-action="checkout" data-order="${c.type==='album'?'Album order':'Card print'}">${icon(c.type==='album'?'shopping-bag':'printer')}<span>${c.type==='album'?'Order':'Print'}</span></button><button data-action="more">${icon('ellipsis')}<span>More</span></button>`:`<button data-action="explore-collection">${icon('disc-3')}<span>View collection</span></button>`}</div>${!readOnly?`<div class="output-links">${textButton('Save image to Photos','export')}${c.type!=='album'?textButton('Write to my DIY cards','write-card'):''}</div>`:''}`}
function albumCards(){return album.cardIds.map(id=>album.snapshots?.find(s=>s.id===id)||getCreation(id)).filter(Boolean)}
function albumDetailView(saved=false){const a=saved?currentItem():album,items=(a.snapshots?.length?a.snapshots:a.cardIds.map(getCreation)).filter(Boolean);return shell(`${ui.physical?`<div class="physical-album"><div class="album-cover">${paperCard({...a,type:'album'},{large:true})}</div><p class="meta">Physical album · cover study</p></div>`:`<div class="album-hero">${paperCard({...a,type:'album'},{large:true})}</div>`}<p class="album-description">${esc(a.description)}</p><div class="preview-switch"><button data-action="digital-preview" aria-pressed="${!ui.physical}">Digital</button><button data-action="physical-preview" aria-pressed="${ui.physical}">Physical</button></div>${a.intro?`<div class="intro-player"><span>Intro sound</span>${ib(player.playing?'pause':'play',player.playing?'Pause album intro':'Play album intro','play')}</div>`:''}${creationGrid(items,{action:'album-preview-card'})}<p class="meta center space-top">${items.length} sound cards · Your chosen order</p>`,{title:a.name,footer:saved?(['explore','shared'].includes(ui.detailOrigin)?detailToolbar(a,false,true):ui.detailOrigin==='gift'?primary('Share with my friend','share-gift')+secondary('Edit this album copy','edit-album')+detailToolbar(a,true):primary('Edit album','edit-album')+detailToolbar(a)):primary(album.editId?'Save changes':'Keep album','save-album'),topAction:''})}
function albumEditView(){return shell(`<form>${field('Album name','album.name',album.name,'text',true)}${row('Cover · optional',album.photo?'Image selected · Change':'Choose an image','album-photo')}${textarea('Description · optional','album.description',album.description)}${row('Template',templates[album.template||0].title,'album-template')}${row('Intro sound · optional',album.intro?'Intro added · Change':'Record or choose a sound','album-intro')}</form>`,{title:album.editId?'Edit your album':'Create an album',footer:primary(album.editId?'Arrange cards':'Add cards','album-next')})}
function giftInfoView(){return shell(`<form>${field('Recipient name','gift.recipient',gift.recipient,'text',true)}<label class="field"><span>Occasion</span><select name="gift.occasion">${['Birthday','Anniversary','Wedding','New beginning','Thank you','Thinking of you','Just because'].map(o=>`<option ${gift.occasion===o?'selected':''}>${o}</option>`).join('')}</select></label></form>`,{title:'Create a gift',topAction:`<button class="top-action" data-go="gift-drafts">View drafts</button>`,footer:primary('Continue','gift-continue')})}
function giftSummaryView(){const c=collections.find(c=>c.id===gift.collection);return shell(`<p class="eyebrow space-bottom">${esc(gift.occasion)}</p>${gift.kind==='set'?row('Speaker',`${['Mountain speaker','Speaker 02','Speaker 03'][gift.speaker||0]} · ${gift.color}`,'gift-speaker'):''}${gift.kind!=='cards'?row('Sound Collection',c?c.title:'Choose a sound collection','gift-bazaar'):''}${gift.kind==='set'?row('Blessing Card',gift.blessing?.name||'Create or edit your message','gift-blessing'):''}${gift.kind==='cards'?`<div class="gift-creations">${creationGrid(gift.items,{columns:gift.items.some(c=>c.type==='album')?2:4,action:'gift-item-detail'})}</div>${row('Add another creation','Create or choose from My Creativity','gift-add-items')}`:''}${row('Preview my gift','Packaging, cards and sound','gift-preview')}<p class="meta space-top">Gift draft saved on this device.</p>`,{title:`A gift for ${gift.recipient}`,footer:gift.kind==='cards'?primary('Share with my friend','share-gift'):primary('Purchase','purchase-gift')})}
function bazaarView(wishlist=false){const q=ui.search.toLowerCase();const items=collections.filter(c=>(!wishlist||db.wishlist.includes(c.id))&&(ui.collectionCategory==='All'||c.category===ui.collectionCategory)&&`${c.title} ${c.creator} ${c.category}`.toLowerCase().includes(q));return shell(`<label class="search-field">${icon('search')}<input name="bazaar-search" placeholder="Album, creator or mood" aria-label="Search Sound Bazaar" value="${esc(ui.search)}"></label><div class="chip-tabs">${['All','Sleep','Focus','Relax','Emotional Healing','Binaural Beats','New Arrivals','Hot Picks'].map(c=>`<button data-action="collection-category" data-value="${c}" class="${ui.collectionCategory===c?'active':''}">${c}</button>`).join('')}</div><div class="bazaar-grid">${items.map(c=>`<article><button class="collection-cover" data-action="collection-preview" data-id="${c.id}" aria-label="Preview ${esc(c.title)}">${art(c)}</button><h2>${c.title}</h2><p class="meta">By ${c.creator} · ${c.category}</p><div class="row between">${ib(db.wishlist.includes(c.id)?'heart-handshake':'heart','Save '+c.title+' to Wishlist','wishlist',{id:c.id})}<button class="text-button" data-action="select-collection" data-id="${c.id}">${gift.collection===c.id?'Selected ✓':'Select'}</button></div></article>`).join('')}</div>${items.length?'':'<div class="empty"><p>No collections found.</p><button class="text-button" data-action="clear-bazaar">Clear search</button></div>'}`,{title:wishlist?'My Wishlist':'Sound Bazaar',subtitle:wishlist?'':'Discover handmade sound albums',topAction:ib('heart','View wishlist','open-wishlist'),footer:primary('Confirm','confirm-collection',!gift.collection)})}
function collectionDetailView(){const c=collections[ui.collection];return shell(`<div class="collection-large">${art(c)}</div><p class="byline">By ${c.creator} · Sound artist</p><p class="subtitle">${c.description}</p><p class="subtitle">For ${c.category.toLowerCase()}, quiet focus, and slower moments.</p><h2 class="section-title">Tracks</h2>${c.tracks.map((t,i)=>`<div class="track-row"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${t}</strong><small>30-second preview</small></div>${ib('play','Preview '+t,'track-preview',{index:i})}</div>`).join('')}${textButton(db.wishlist.includes(c.id)?'Remove from Wishlist':'Add to Wishlist','collection-wishlist')}`,{title:c.title,footer:(ui.bazaarSource==='explore'?'':primary('Confirm','collection-confirm'))+secondary('Purchase Now','collection-purchase')})}
function photoView(){return shell(row('Artist Collection','Backgrounds created by artists for Journey in Me.','artist-photos')+row('Your Photos','Choose an image from your library.','own-photos')+'<p class="meta space-top">Choose an image for your card.</p>',{title:'Choose an image'})}
function artistView(){return shell(`<div class="chip-tabs">${['All','Nature','Texture'].map(c=>`<button class="${c===ui.artistCategory?'active':''}" data-action="art-category" data-value="${c}">${c}</button>`).join('')}</div><div class="artist-grid">${artNames.map((n,i)=>({n,i})).filter(({i})=>ui.artistCategory==='All'||(ui.artistCategory==='Nature'?i<6:i>=6)).map(({n,i})=>`<button data-action="pick-art" data-index="${i}" aria-label="Choose ${n}">${art({art:i%4})}<span>${n}</span></button>`).join('')}</div><p class="meta space-top">Paper Zen colour studies · artwork selection to follow.</p>`,{title:'Artist Collection'})}
function photosView(){return shell(`<label class="photo-upload"><span>${icon('image-plus')}</span><strong>Choose from your photos</strong><small>JPG, PNG, or WebP · stays on this device</small><input type="file" accept="image/jpeg,image/png,image/webp" id="photo-input"></label><p class="subtitle">Choose one image, then adjust the crop.</p>`,{title:'Your Photos'})}
function cropView(){return shell(`<div class="crop-area" id="crop-area">${art({photo:ui.pendingPhoto,art:ui.pendingArt})}</div>${ui.pendingPhoto?.startsWith('data:')?`<label class="range-label space-top">Size <input type="range" name="crop-scale" min="1" max="2.5" step=".05" value="${ui.cropScale||1}"></label><label class="range-label">Horizontal position <input type="range" name="crop-x" min="0" max="100" value="${ui.cropX??50}"></label><label class="range-label">Vertical position <input type="range" name="crop-y" min="0" max="100" value="${ui.cropY??50}"></label>`:'<p class="meta center space-top">Your selected background</p>'}`,{title:'Adjust your photo',footer:primary('Use photo','use-photo')})}
function speakerView(){const speaker=ui.speaker;return shell(`<div class="speaker-carousel" data-swipe="speaker">${ib('chevron-left','Previous speaker','speaker-prev')}${speaker===0?`<div class="speaker-art"><div class="speaker-crop"><img src="assets/speaker-transparent.png" alt="Mountain speaker with white mountain-shaped top"></div></div>`:`<div class="speaker-pending"><span>${icon('speaker')}</span><p>Speaker ${speaker+1}</p><small>Product image to be confirmed</small></div>`}${ib('chevron-right','Next speaker','speaker-next')}</div><h2 class="center">${['Mountain speaker','Speaker 02','Speaker 03'][speaker]}</h2><div class="carousel-dots">${[0,1,2].map(i=>`<span class="dot ${i===speaker?'selected':''}"></span>`).join('')}</div><details class="speaker-options" open><summary>Speaker option ${icon('chevron-down')}</summary><label class="field"><span>Color</span><select name="gift.color">${['Paper white','Warm oat','Moss'].map(v=>`<option ${gift.color===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('Engraving','gift.engraving',gift.engraving)}<div class="price-row"><span>Price</span><span>Confirmed at checkout</span></div></details>`,{title:'Choose a speaker',footer:primary('Confirm speaker','confirm-speaker')})}
function shareView(isExport=false){const c=ui.shareItem||currentItem();const wholeGift=c.type==='gift';const preview=wholeGift?(c.items?.[0]||c.blessing||{name:collections.find(x=>x.id===c.collection)?.title||'A gift for you',art:0}):c;return shell(`<div class="share-preview">${wholeGift?`<h2>A gift for ${esc(c.recipient)}</h2><p class="meta">${c.items?.length||1} ${c.items?.length>1?'creations':'creation'} · Made for you</p>`:''}${paperCard(preview,{large:true,qr:true})}${c.type==='album'?`<p class="meta center">Album · ${c.cardIds?.length||0} sound cards</p>`:''}</div>${isExport?'':`<div class="share-channels"><button data-action="share-channel" data-channel="Instagram">${icon('camera')}<span>Instagram</span></button><button data-action="share-channel" data-channel="WeChat">${icon('message-circle')}<span>WeChat</span></button><button data-action="native-share">${icon('ellipsis')}<span>More</span></button><button data-action="copy-link">${icon('link')}<span>Copy link</span></button></div>`}<p class="meta center space-top">Demo link · available on this device</p>`,{title:'',footer:isExport?primary('Save image to Photos','download-image'):''})}
function writeView(){const step=ui.writingStep;const data=[['Connect your speaker','Turn on your speaker and check the connection.','Check connection'],['Insert your DIY card','Place your card in the speaker.','Check card'],['Ready to write','The speaker and your card are ready.','Start writing'],['Writing your card','Keep the speaker connected and the card in place.',''],['Your card is ready','Your sound is ready to play on your speaker.','Back to your creation']][step];return shell(`<p class="demo-label">HARDWARE SIMULATION</p><div class="write-step-indicator">${[0,1,2,3,4].map((n)=>`<span class="${step>=n?'complete':''}">${n+1}</span>`).join('')}</div><div class="speaker-art writing-speaker"><div class="speaker-crop"><img src="assets/speaker-transparent.png" alt="Mountain speaker"></div></div><h2 class="center">${data[0]}</h2><p class="subtitle center">${data[1]}</p>${step===3?'<progress id="write-progress" value="0" max="100" aria-label="Writing progress"></progress><p class="meta center" id="write-percent">0%</p>':''}${step===0?`<label class="demo-check"><input type="checkbox" name="demo-connected" ${ui.hardwareConnected?'checked':''}> Simulate a connected speaker</label>`:''}${step===1?`<label class="demo-check"><input type="checkbox" name="demo-card" ${ui.hardwareCard?'checked':''}> Simulate an inserted card</label><label class="demo-check"><input type="checkbox" name="demo-used-card" ${ui.usedCard?'checked':''}> Card already has content</label>`:''}<p class="meta center space-top">This demo does not connect to a physical speaker.</p>`,{title:'Write to my DIY cards',footer:data[2]?primary(data[2],'write-next'):secondary('Simulate a disconnection','write-fail')})}
function checkoutView(){return shell(`<p class="demo-label">SHOPIFY HANDOFF · DEMO</p><div class="order-summary">${icon('shopping-bag')}<div><h2>${esc(ui.order)}</h2><p class="subtitle">Order details, price and payment are confirmed in Shopify.</p></div></div>${row('Delivery','Shipping address is entered at checkout','checkout-info')}${row('Payment','No payment is collected in this demo','checkout-info')}<p class="meta space-top">Choose a simulated result to test the return to Journey in Me.</p><div class="stack space-top">${primary('Simulate successful payment','order-success')}${secondary('Simulate cancelled checkout','order-cancel')}${textButton('Simulate an unverified result','order-pending')}</div>`,{title:ui.order==='Card print'?'Print your card':'Checkout'})}
function render(){const motionBefore=beforeRender(app,route);giftCinema?.destroy();giftCinema=null;let html;switch(route){
case 'home':html=`<div class="view"><div class="content home-screen"><h1 class="brand">Journey in Me</h1><section class="practice-count"><p>You’ve practiced for</p><strong>356</strong><span>days.</span></section><button class="home-link" data-go="reflection">Reflection ${icon('chevron-right')}</button><button class="home-link" data-go="friends">Friends ${icon('chevron-right')}</button></div>${nav('home')}</div>`;break;
case 'create':html=shell(`<div class="creation-menu">${[['memory','bookmark','Memory','A moment worth keeping.'],['gift','gift','Gift','Something made for someone.'],['new-simple','square-pen','A Simple Card','An image, a few words, your voice.'],['new-album','layers','My Album','Bring your sound cards together.']].map(([action,i,t,d])=>`<button class="creation-entry" data-action="${action}"><span class="entry-mark">${icon(i)}</span><span><h2>${t}</h2><p>${d}</p></span>${icon('chevron-right')}</button>`).join('')}</div><div class="creation-links"><button data-go="library"><span>My Creativity<small>The things you’ve made.</small></span>${icon('chevron-right')}</button><button data-go="explore"><span>What a creative world !?<small>Explore warm creations shared by everyone.</small></span>${icon('chevron-right')}</button></div>`,{title:'Create',back:false,navigation:'create'});break;
case 'memory':html=shell(memoryThemes().map((t,i)=>row(t.title,t.custom?'Your theme':'','memory-theme',{index:i})).join('')+customOption('Create a custom theme','A category that feels like you.','custom-theme'),{title:'What would you like to remember?',subtitle:'Start with what made this moment meaningful.'});break;
case 'subtheme':{const theme=selectedMemoryTheme();html=shell(memorySubthemes(theme).map(t=>row(t,'','memory-subtheme',{value:t})).join('')+customOption('Create a custom moment','Give this memory its own name.','custom-subtheme'),{title:theme.title,subtitle:theme.description||'What would you like to keep?'});break;}
case 'template':html=templateView();break;
case 'editor':html=editorView();break;
case 'photo':html=photoView();break;
case 'artist':html=artistView();break;
case 'photos':html=photosView();break;
case 'crop':html=cropView();break;
case 'sound':html=soundView();break;
case 'recording':html=recordingView();break;
case 'sound-library':html=soundLibraryView();break;
case 'mixer':html=mixerView();break;
case 'generating':html=shell(`<div class="empty"><span class="loading-mark">${icon('disc-3')}</span><h2>Keeping your moment.</h2><p>Your words, image, and sound are coming together.</p>${textButton('View in My Creativity','leave-generating')}</div>`,{title:'Creating your card'});break;
case 'detail':html=detailView();break;
case 'library':html=libraryView();break;
case 'gift-picker':html=libraryView({selection:true});break;
case 'explore':html=shell(creationGrid([...seedCards.slice(0,8),...seedAlbums],{creator:true,action:'explore-detail'}),{title:'What a creative world !?',subtitle:'Explore warm creations shared by everyone.',navigation:'create'});break;
case 'album':html=albumEditView();break;
case 'album-cards':html=shell(`<p class="meta space-bottom">${album.cardIds.length} / 10 cards selected</p>${row('Create a new card','Make a card for this album','album-new-card')}<p class="section-label">Choose from My Creativity</p>${creationGrid(db.cards,{multi:true,selected:album.cardIds,action:'album-select'})}<p class="meta space-top">Select up to 10 cards.</p>`,{title:'Add sound cards',footer:primary('Continue','arrange-cards',!album.cardIds.length)});break;
case 'album-arrange':html=shell(creationGrid(albumCards(),{reorder:true,action:'noop'})+textButton('Add more cards','album-add-cards'),{title:'Arrange your cards',subtitle:'Drag to change the order, or tap a card’s menu.',footer:primary('Preview album','preview-album',!album.cardIds.length)});break;
case 'album-preview':html=albumDetailView(false);break;
case 'album-detail':html=albumDetailView(true);break;
case 'gift':html=giftInfoView();break;
case 'gift-types':html=shell(row('A complete gift set','A player, sounds cards, and your personal message.','gift-type',{value:'set'})+row('Craft Unique Cards for your friends','Create one card or a collection from your creativity','gift-type',{value:'cards'})+row('Choose something lovely to my friend','Choose meaningful sounds collection to companion your friends','gift-type',{value:'collection'}),{title:'What would you like to give?'});break;
case 'gift-card-choice':html=shell(row('Create now','Make something for '+gift.recipient,'gift-create-card')+row('Choose from My Creativity','Select one or more cards and albums','gift-pick-items'),{title:'Craft unique cards',subtitle:'A little of you, for '+gift.recipient+'.'});break;
case 'gift-summary':html=giftSummaryView();break;
case 'gift-speaker':html=speakerView();break;
case 'gift-preview':{const visual=gift.blessing||gift.items[0]||{name:collections.find(c=>c.id===gift.collection)?.title||'A gift for you',art:0};ui.flipped=false;html=giftPreviewMarkup({gift,cardMarkup:paperCard(visual,{large:true}),icon,esc});break;}
case 'gift-drafts':html=shell(db.giftDrafts.length?db.giftDrafts.map(g=>row(`A gift for ${g.recipient}`,g.occasion,'resume-gift',{id:g.id})).join(''):'<div class="empty"><p>Your gift drafts will appear here after the gift summary.</p></div>',{title:'Gift drafts'});break;
case 'bazaar':html=bazaarView();break;
case 'wishlist':html=bazaarView(true);break;
case 'collection':html=collectionDetailView();break;
case 'share':html=shareView();break;
case 'export':html=shareView(true);break;
case 'write':html=writeView();break;
case 'checkout':html=checkoutView();break;
case 'order-result':html=shell(`<div class="empty"><span class="result-icon">${icon(ui.orderStatus==='success'?'check':ui.orderStatus==='pending'?'clock-3':'arrow-left')}</span><h2>${ui.orderStatus==='success'?'Order confirmed':ui.orderStatus==='pending'?'Order pending verification':'Checkout not completed'}</h2><p>${ui.orderStatus==='success'?'Your simulated payment was confirmed.':ui.orderStatus==='pending'?'Returning to the app does not confirm a payment.':'No payment was made.'}</p><p class="meta">Demo order · no charge</p></div>`,{title:'Order status',footer:(ui.orderStatus==='pending'?secondary('Check again','order-recheck'):'')+primary('Back to your creation','order-return')});break;
case 'public-card':{let target;try{target=JSON.parse(localStorage.getItem('journey-share-'+new URLSearchParams(location.hash.split('?')[1]).get('id')))}catch{}if(target){ui.sharedItems=target.type==='gift'?(target.items.length?target.items:target.blessing?[target.blessing]:[]):target.type==='album'?target.snapshots||[]:[];const cover=target.type==='gift'?(ui.sharedItems[0]||{name:collections.find(c=>c.id===target.collection)?.title||'A gift for you'}):target;html=shell(paperCard(cover,{large:true})+mediaPlayer()+ (ui.sharedItems.length?creationGrid(ui.sharedItems,{action:'shared-item'}):''),{title:target.name||'A gift for '+target.recipient})}else html=shell('<div class="empty"><p>This demo link is only available in the browser where it was created.</p></div>',{title:'A little moment'});break;}
case 'reflection':case 'friends':case 'practice':case 'share-hub':html=shell(`<div class="empty"><h2>${({reflection:'Reflection',friends:'Friends',practice:'Practice','share-hub':'Share'})[route]}</h2><p>This demo focuses on Create.</p>${primary('Explore Create','create')}</div>`,{navigation:route==='practice'?'practice':route==='share-hub'?'share-hub':'home'});break;
default:html=shell('<div class="empty"><p>This page is not available.</p></div>',{title:'Journey in Me',footer:primary('Back to Create','create')});}
app.innerHTML=html;rememberUI();icons();if(route==='editor')syncCardValidation();if(route==='share'||route==='export')renderQR();if(route==='crop')updateCrop();updatePlayer();afterRender(app,route,motionBefore);if(route==='gift-preview')mountGift();}
function updatePlayer(){giftCinema?.audioChanged(player.playing);const intro=document.querySelector('.intro-player button');if(intro){const label=player.playing?'Pause album intro':'Play album intro';if(intro.getAttribute('aria-label')!==label){intro.setAttribute('aria-label',label);intro.innerHTML=icon(player.playing?'pause':'play');icons()}}document.querySelectorAll('[data-current]').forEach(n=>n.textContent=time(player.current));document.querySelectorAll('[data-duration]').forEach(n=>n.textContent=time(player.duration));document.querySelectorAll('[data-audio-progress]').forEach(n=>{n.max=player.duration;n.value=player.current;n.style.setProperty('--progress',100*player.current/player.duration+'%')});document.querySelectorAll('.play-button').forEach(b=>{const label=player.playing?'Pause':'Play';if(b.getAttribute('aria-label')!==label){b.setAttribute('aria-label',label);b.innerHTML=icon(player.playing?'pause':'play');icons()}})}
function openModal(title,content,buttons){if(modal.open)modal.close();modal.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${content}${buttons}`;modal.setAttribute('aria-labelledby','dialog-title');modal.showModal();icons();animateDialog(modal);(modal.querySelector('input,textarea')||(/delete|remove|replace|reset/i.test(title)?modal.querySelector('[data-action=close-modal]'):null)||modal.querySelector('button'))?.focus()}
function closeModal(){if(modal.open)modal.close();player.pause()}
function giftSave(){gift.id=gift.id||uid('gift');gift.savedAt=today();db.giftDrafts=db.giftDrafts.filter(g=>g.id!==gift.id);db.giftDrafts.unshift(clone(gift));persist()}
function openGiftSummary(){giftSave();go('gift-summary')}
function shareItem(item,kind='share'){ui.shareItem=clone(item);ui.shareReturn=route;ui.shareToken=uid('share');try{localStorage.setItem('journey-share-'+ui.shareToken,JSON.stringify(item))}catch{}ui.shareUrl=location.origin+location.pathname+'#/public-card?id='+ui.shareToken;ui.flipped=false;go(kind)}
function renderQR(){const el=$('.qr-target');if(!el)return;if(window.qrcode){const qr=window.qrcode(0,'M');qr.addData(ui.shareUrl||location.href);qr.make();el.innerHTML=qr.createSvgTag({cellSize:2,margin:1})+'<small>Listen</small>'}else el.innerHTML=icon('qr-code')+'<small>Demo link</small>'}
function saveCompleteCard(){let created={...card,status:'completed',date:card.date||today()};delete created.editId;db.cards=db.cards.filter(c=>c.id!==(card.editId||created.id));db.cards.unshift(created);db.drafts=db.drafts.filter(d=>d.id!==card.id);card=created;persist();if(card.source==='gift'&&!card.editId){if(gift.kind==='set')gift.blessing=clone(created);else if(ui.replaceGiftCard){gift.items=gift.items.map(c=>c.id===ui.replaceGiftCard?clone(created):c);ui.replaceGiftCard=null;}else gift.items=[...gift.items.filter(c=>c.id!==created.id),clone(created)];giftSave();}return created}
async function generateCard(){if(route!=='editor')return;ui.error='';ui.cardValidationFor=card.id;const errors=cardErrors(card);rememberUI();syncCardValidation();if(Object.keys(errors).length){focusFirstCardError(errors);return}go('generating');activeGeneration=card.id;setTimeout(()=>{if(activeGeneration!==card.id)return;const c=saveCompleteCard();activeGeneration=null;if(route==='generating'){if(c.source==='gift'&&gift.kind==='set')openGiftSummary();else openDetail(c,c.source==='gift'?'gift':c.source==='album'?'album-new':'created')}else {if(route==='library')render();notify('Your card is ready in My Creativity.');}},900)}
async function startRecording(){try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});chunks=[];recorder=new MediaRecorder(recordStream,{audioBitsPerSecond:32000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});const reader=new FileReader();reader.onload=()=>{ui.recordBlob=reader.result;player.configure({voice:ui.recordBlob,background:false,limit:ui.recordSeconds||null});ui.recordStage='review';stopRecordingTracks();if(route==='recording')render()};reader.readAsDataURL(blob)};recorder.start();ui.recordSeconds=0;ui.recordStage='recording';ui.recordPaused=false;recStarted=Date.now();recordTimer=setInterval(()=>{if(!ui.recordPaused)ui.recordSeconds++;if($('#record-time'))$('#record-time').textContent=time(ui.recordSeconds);if(ui.recordSeconds>=120&&recorder?.state!=='inactive')recorder.stop()},1000);render()}catch{ui.error='Microphone access is unavailable. Try again, or use a demo recording.';ui.recordStage='permission';render()}}
function stopRecordingTracks(){clearInterval(recordTimer);recordStream?.getTracks().forEach(t=>t.stop());recordStream=null}
async function loadPhoto(file){if(!file)return;ui.cropReturn='photos';if(file.size>15*1024*1024){notify('Choose an image under 15 MB.');return}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const img=await imageFrom(data);const canvas=document.createElement('canvas');let scale=Math.min(1,1600/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);ui.pendingPhoto=canvas.toDataURL('image/jpeg',.88);ui.cropScale=1;ui.cropX=50;ui.cropY=50;go('crop')}catch{ui.error='This photo could not be added. Choose another image.';render()}}
function imageFrom(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src=src})}
function updateCrop(){const img=$('#crop-area img');if(img){img.style.transform=`scale(${ui.cropScale||1})`;img.style.objectPosition=`${ui.cropX??50}% ${ui.cropY??50}%`}}
async function usePhoto(){let photo=ui.pendingPhoto;if(photo?.startsWith('data:')){const image=await imageFrom(photo),c=document.createElement('canvas');c.width=c.height=1000;const size=Math.min(image.width,image.height)/(ui.cropScale||1),sx=(image.width-size)*(ui.cropX??50)/100,sy=(image.height-size)*(ui.cropY??50)/100;c.getContext('2d').drawImage(image,sx,sy,size,size,0,0,1000,1000);photo=c.toDataURL('image/jpeg',.9)}const target=ui.photoFor==='album'?album:card;target.photo=photo;target.art=ui.pendingArt||0;persist();go(ui.photoReturn)}
async function downloadImage(){const c=ui.shareItem?.type==='gift'?(ui.shareItem.items[0]||ui.shareItem.blessing):ui.shareItem||currentItem();if(!c){notify('Choose a creation first.');return}try{const canvas=document.createElement('canvas');canvas.width=1400;canvas.height=1750;const ctx=canvas.getContext('2d');ctx.fillStyle='#FAFAF7';ctx.fillRect(0,0,1400,1750);if(c.photo?.startsWith('data:')){ctx.drawImage(await imageFrom(c.photo),64,64,1272,1272)}else{const palettes=[['#a4b799','#567b70','#dcd69e'],['#b9d7c4','#94b3a0','#d5c272'],['#c0dcca','#5b989d','#d7d295'],['#bac9c4','#5c7a83','#d4d0ad']];const p=palettes[(c.art||0)%4],g=ctx.createLinearGradient(64,64,1336,1336);g.addColorStop(0,p[0]);g.addColorStop(.45,p[1]);g.addColorStop(1,p[2]);ctx.fillStyle=g;ctx.fillRect(64,64,1272,1272)}ctx.fillStyle='#36443b';ctx.font='52px Georgia';wrapText(ctx,c.name,64,1440,1000,62);ctx.font='25px sans-serif';ctx.fillText('JOURNEY IN ME',64,1680);if(window.qrcode){const qr=window.qrcode(0,'M');qr.addData(ui.shareUrl);qr.make();const n=qr.getModuleCount(),size=210,cell=size/n;ctx.fillStyle='#fff';ctx.fillRect(1090,1460,240,240);ctx.fillStyle='#303730';for(let r=0;r<n;r++)for(let col=0;col<n;col++)if(qr.isDark(r,col))ctx.fillRect(1105+col*cell,1475+r*cell,Math.ceil(cell),Math.ceil(cell))}const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=(c.name||'Journey in Me')+'.png';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),5000);notify('Image downloaded. You can save it to Photos.')}catch{notify('Image could not be saved. Please try again.')}}
function wrapText(ctx,text,x,y,width,lineHeight){let line='';for(const word of text.split(' ')){if(ctx.measureText(line+word).width>width){ctx.fillText(line,x,y);line='';y+=lineHeight}line+=word+' '}ctx.fillText(line,x,y)}
async function copyLink(){try{await navigator.clipboard.writeText(ui.shareUrl);notify('Demo link copied. It opens on this device.')}catch{openModal('Copy link',`<p>Copy this demo link:</p><input readonly value="${esc(ui.shareUrl)}">`,secondary('Close','close-modal'))}}
function moreMenu(){const c=currentItem();openModal(c.name||'More options',`<div class="menu-list">${row('Save image to Photos','','export')}${c.type==='card'?row('Write to my DIY cards','','write-card'):row('Publish and sell','Coming soon','noop',{},true)}${ui.detailOrigin!=='explore'?row('Delete creation','Removes it from your library','delete-confirm'):''}</div>`,secondary('Close','close-modal'))}
function beginCheckout(order){ui.order=order;ui.orderReturn=route;go('checkout')}
async function action(name,d={}){switch(name){
case 'noop':return;
case 'custom-theme':openCustomMemory('theme');break;
case 'custom-subtheme':openCustomMemory('subtheme');break;
case 'save-custom-memory':saveCustomMemory();break;
case 'arrange-card-menu':openArrangeMenu(d.id);break;
case 'back':back();break;
case 'create':go('create');break;
case 'memory':go('memory');break;
case 'memory-theme':ui.theme=+d.index;go('subtheme');break;
case 'memory-subtheme':beginCard('memory',selectedMemoryTheme().title,d.value);break;
case 'new-simple':beginCard('simple');break;
case 'change-template':ui.templateReturn='editor';ui.template=card.template;ui.templateFor='card';go('template');break;
case 'prev-template':ui.template=(ui.template+2)%3;render();break;
case 'next-template':ui.template=(ui.template+1)%3;render();break;
case 'set-template':ui.template=+d.index;render();break;
case 'use-template':if(ui.templateFor==='album'){album.template=ui.template;ui.templateFor='card';persist();go('album')}else{card.template=ui.template;saveDraft();go('editor')}break;
case 'card-photo':ui.photoFor='card';ui.photoReturn='editor';go('photo');break;
case 'album-photo':ui.photoFor='album';ui.photoReturn='album';go('photo');break;
case 'artist-photos':go('artist');break;
case 'own-photos':go('photos');break;
case 'art-category':ui.artistCategory=d.value;render();break;
case 'pick-art':ui.cropReturn='artist';ui.pendingArt=+d.index%4;ui.pendingPhoto='art:'+ui.pendingArt;go('crop');break;
case 'use-photo':await usePhoto();break;
case 'card-sound':ui.soundFor='card';ui.soundReturn='editor';go('sound');break;
case 'record-start':ui.recordStage='permission';go('recording');break;
case 'allow-mic':await startRecording();break;
case 'demo-recording':ui.recordBlob='demo';ui.recordStage='review';player.configure({limit:30});render();break;
case 'record-again':ui.recordStage='permission';player.pause();render();break;
case 'record-pause':if(recorder?.state==='recording'){recorder.pause();ui.recordPaused=true}else if(recorder?.state==='paused'){recorder.resume();ui.recordPaused=false}render();break;
case 'record-stop':clearInterval(recordTimer);if(recorder?.state!=='inactive')recorder?.stop();break;
case 'record-cancel':if(recorder&&recorder.state!=='inactive')recorder.stop();stopRecordingTracks();go('sound');break;
case 'use-recording':soundState().recording=ui.recordBlob||'demo';soundState().recordingDuration=ui.recordBlob==='demo'?30:ui.recordSeconds;soundState().mixed=false;persist();go('sound');break;
case 'sound-library':ui.pickSound=null;ui.soundExpanded=false;go('sound-library');break;
case 'sound-category':ui.soundCategory=d.value;render();break;
case 'preview-sound':ui.pickSound=d.id;player.configure();render();break;
case 'expand-sound':ui.soundExpanded=!ui.soundExpanded;render();break;
case 'close-sound':player.pause();ui.pickSound=null;ui.soundExpanded=false;render();break;
case 'use-sound':soundState().sound=ui.pickSound;soundState().mixed=false;persist();go('sound');break;
case 'mixer':configureSound();go('mixer');break;
case 'save-mix':soundState().mixed=true;persist();go('sound');break;
case 'sound-done':if(ui.soundFor==='intro'){album.intro=clone(soundState());persist()}else saveDraft();go(ui.soundReturn);break;
case 'remove-intro':album.intro=null;album.introDraft=null;persist();go('album');break;
case 'play':try{await player.toggle()}catch{notify('Audio could not play. Tap play to retry.')}break;
case 'rewind':player.seek(player.current-15);break;
case 'forward':player.seek(Math.min(player.current+15,player.duration));break;
case 'replay':player.seek(0);if(!player.playing)await player.toggle().catch(()=>notify('Tap play to enable sound.'));break;
case 'generate-card':await generateCard();break;
case 'leave-generating':go('library');break;
case 'open-detail':openDetail(getCreation(d.id));break;
case 'shared-item':openDetail(ui.sharedItems.find(c=>c.id===d.id),'shared');break;
case 'explore-detail':openDetail(seedCards.find(c=>c.id===d.id)||seedAlbums.find(c=>c.id===d.id),'explore');break;
case 'flip-card':ui.flipped=!ui.flipped;render();break;
case 'edit-card':{const c=clone(currentItem());if(ui.detailOrigin==='gift'){ui.replaceGiftCard=c.id;c.id=uid('card');c.source='gift';delete c.editId}else {c.editId=c.id;c.source='simple';}card=c;go('editor');break;}
case 'library-type':ui.libraryType=d.value;render();break;
case 'library-status':ui.libraryStatus=d.value;render();break;
case 'resume-draft':{const a=db.albumDrafts.find(x=>x.id===d.id);if(a){album=clone(a);go('album')}else{card=clone(db.drafts.find(c=>c.id===d.id));go('editor')}break;}
case 'new-album':ui.albumForGift=false;album=newAlbum();persist();go('album');break;
case 'album-template':ui.templateReturn='album';ui.templateFor='album';ui.template=album.template||0;go('template');break;
case 'album-intro':ui.soundFor='intro';ui.soundReturn='album';go('sound');break;
case 'album-next':if(!album.name.trim()){ui.error='Enter an album name.';render();return}persist();go(album.editId?'album-arrange':'album-cards');break;
case 'album-select':if(album.cardIds.includes(d.id))album.cardIds=album.cardIds.filter(id=>id!==d.id);else if(album.cardIds.length<10)album.cardIds.push(d.id);else notify('Your album is full. Remove a card to add another.');persist();render();break;
case 'album-new-card':if(album.cardIds.length===10){notify('Your album already has 10 cards.');return}beginCard('album');break;
case 'back-to-album':if(!album.cardIds.includes(card.id)&&album.cardIds.length<10)album.cardIds.push(card.id);persist();go('album-cards');break;
case 'arrange-cards':go('album-arrange');break;
case 'album-add-cards':go('album-cards');break;
case 'remove-album-card':ui.removeCard=d.id;openModal('Remove this card?','<p>It will stay in My Creativity. Only the album changes.</p>',primary('Remove from album','remove-album-confirm')+secondary('Keep card','close-modal'));break;
case 'remove-album-confirm':album.cardIds=album.cardIds.filter(id=>id!==ui.removeCard);closeModal();persist();render();break;
case 'move-card':{closeModal();const i=album.cardIds.indexOf(d.id),j=i+ +d.dir;if(j>=0&&j<album.cardIds.length)[album.cardIds[i],album.cardIds[j]]=[album.cardIds[j],album.cardIds[i]];persist();render();break;}
case 'preview-album':album.snapshots=clone(albumCards());ui.physical=false;if(album.intro)player.configure({voice:album.intro.recording,background:!!album.intro.sound});go('album-preview');break;
case 'save-album':{const a={...clone(album),status:'completed',date:today()};delete a.editId;db.albums=db.albums.filter(x=>x.id!==a.id);db.albums.unshift(a);db.albumDrafts=db.albumDrafts.filter(x=>x.id!==a.id);album=a;persist();if(ui.albumForGift){gift.items=gift.items.map(c=>c.id===ui.replaceGiftAlbum?clone(a):c);giftSave();openDetail(a,'gift')}else openDetail(a);break;}
case 'edit-album':album=clone(currentItem());ui.albumForGift=ui.detailOrigin==='gift';if(ui.albumForGift){ui.replaceGiftAlbum=album.id;album.id=uid('album');delete album.editId}else album.editId=album.id;album.status='draft';go('album');break;
case 'album-preview-card':{const a=route==='album-detail'?currentItem():album;const c=a.snapshots.find(x=>x.id===d.id)||getCreation(d.id);ui.parentDetail={item:clone(a),origin:ui.detailOrigin,route};openDetail(c,ui.detailOrigin==='explore'?'explore':'album-view');break;}
case 'digital-preview':ui.physical=false;render();break;
case 'physical-preview':ui.physical=true;render();break;
case 'gift':gift={recipient:'',occasion:'Birthday',kind:'',items:[],speaker:0,color:'Paper white',engraving:'',collection:null};persist();go('gift');break;
case 'gift-continue':if(!gift.recipient.trim()){ui.error='Enter the recipient’s name.';render();return}persist();go('gift-types');break;
case 'gift-type':ui.bazaarSource='gift';gift.kind=d.value;persist();if(gift.kind==='set'){ui.speaker=gift.speaker;go('gift-speaker')}else go(gift.kind==='cards'?'gift-card-choice':'bazaar');break;
case 'gift-speaker':ui.speaker=gift.speaker||0;go('gift-speaker');break;
case 'speaker-prev':ui.speaker=(ui.speaker+2)%3;render();break;
case 'speaker-next':ui.speaker=(ui.speaker+1)%3;render();break;
case 'confirm-speaker':gift.speaker=ui.speaker;openGiftSummary();break;
case 'gift-bazaar':ui.bazaarSource='gift';ui.search='';ui.collectionCategory='All';go('bazaar');break;
case 'gift-blessing':if(gift.blessing){card=clone(gift.blessing);card.source='gift';card.id=uid('card');delete card.editId;go('editor')}else{beginCard('gift');card.words=`Dear ${gift.recipient}, `}break;
case 'gift-create-card':beginCard('gift');card.words=`Dear ${gift.recipient}, `;break;
case 'gift-pick-items':ui.selected=gift.items.map(c=>c.id);go('gift-picker');break;
case 'gift-add-items':go('gift-card-choice');break;
case 'selection-type':ui.selectionType=d.value;render();break;
case 'gift-select':ui.selected=ui.selected.includes(d.id)?ui.selected.filter(id=>id!==d.id):[...ui.selected,d.id];render();break;
case 'confirm-gift-items':gift.items=ui.selected.map(getCreation).filter(Boolean).map(clone);openGiftSummary();break;
case 'gift-item-detail':openDetail(gift.items.find(c=>c.id===d.id),'gift');break;
case 'gift-preview':go('gift-preview');break;
case 'gift-toggle':giftCinema?.toggle();break;
case 'gift-replay':giftCinema?.replay();break;
case 'gift-next':giftCinema?.next();break;
case 'gift-skip':giftCinema?.skip();break;
case 'gift-sound':giftCinema?.toggleSound();break;
case 'gift-motion':giftCinema?.toggleMotion();break;
case 'gift-enable-audio':giftCinema?.enableAudio();break;
case 'gift-preview-back':go('gift-summary',{remember:false});break;
case 'resume-gift':gift=clone(db.giftDrafts.find(g=>g.id===d.id));go('gift-summary');break;
case 'purchase-gift':if(gift.kind==='set'&&(!gift.collection||!gift.blessing)){ui.error='Choose a sound collection and add a blessing card first.';render();return}if(!gift.collection&&gift.kind==='collection'){ui.error='Choose a sound collection first.';render();return}beginCheckout('Gift for '+gift.recipient);break;
case 'collection-category':ui.collectionCategory=d.value;render();break;
case 'clear-bazaar':ui.search='';ui.collectionCategory='All';render();break;
case 'open-wishlist':ui.collectionCategory='All';ui.search='';go('wishlist');break;
case 'wishlist':db.wishlist=db.wishlist.includes(d.id)?db.wishlist.filter(id=>id!==d.id):[...db.wishlist,d.id];persist();render();break;
case 'select-collection':gift.collection=d.id;persist();render();break;
case 'collection-preview':{ui.collection=collections.findIndex(c=>c.id===d.id);const c=collections[ui.collection];player.configure({limit:30});openModal(c.title,art(c)+'<p class="meta">By '+c.creator+' · Free preview · 30 seconds</p>'+mediaPlayer({replay:true}),primary('View album','view-collection')+secondary('Close','close-modal'));break;}
case 'view-collection':closeModal();go('collection');break;
case 'collection-wishlist':await action('wishlist',{id:collections[ui.collection].id});break;
case 'collection-confirm':gift.collection=collections[ui.collection].id;openGiftSummary();break;
case 'confirm-collection':openGiftSummary();break;
case 'collection-purchase':beginCheckout(collections[ui.collection].title);break;
case 'track-preview':player.configure({limit:30});await player.toggle().catch(()=>notify('Tap play to enable sound.'));notify('Playing a 30-second demo preview.');break;
case 'explore-collection':ui.bazaarSource='explore';ui.collection=0;go('collection');break;
case 'share':closeModal();shareItem(currentItem());break;
case 'share-gift':closeModal();shareItem({...clone(gift),type:'gift'});break;
case 'export':closeModal();shareItem(currentItem(),'export');break;
case 'share-channel':openModal('Share to '+d.channel,'<p>Save the card image, then share it from '+d.channel+'. This demo does not post to your account.</p>',primary('Save image','download-image')+secondary('Copy demo link','copy-link')+textButton('Close','close-modal'));break;
case 'copy-link':await copyLink();break;
case 'native-share':if(navigator.share){try{await navigator.share({title:ui.shareItem?.name||'Journey in Me',url:ui.shareUrl})}catch(e){if(e.name!=='AbortError')notify('Sharing could not open. Try Copy link.')}}else await copyLink();break;
case 'download-image':await downloadImage();break;
case 'more':moreMenu();break;
case 'delete-confirm':openModal('Delete this creation?','<p>Shared gifts and copies inside albums will stay available. This removes the creation from your personal library.</p>',primary('Delete creation','delete-creation')+secondary('Keep creation','close-modal'));break;
case 'delete-creation':{const c=currentItem();db.snapshots[c.id]=clone(c);db[c.type==='album'?'albums':'cards']=db[c.type==='album'?'albums':'cards'].filter(x=>x.id!==c.id);closeModal();persist();go('library');notify('Creation removed from your library.');break;}
case 'write-card':closeModal();ui.writingStep=0;ui.writeReturn=route;ui.hardwareConnected=false;ui.hardwareCard=false;ui.usedCard=false;go('write');break;
case 'write-next':if(ui.writingStep===0&&!ui.hardwareConnected){ui.error='Speaker is not connected. Check the simulated connection and try again.';render();return}if(ui.writingStep===1&&!ui.hardwareCard){ui.error='Card not detected. Insert a card and check again.';render();return}if(ui.writingStep===2&&ui.usedCard){openModal('Replace the sound on this card?','<p>The existing sound on this DIY card will be replaced.</p>',primary('Replace and write','write-confirm')+secondary('Keep existing sound','close-modal'));return}if(ui.writingStep===4){go(ui.writeReturn||'detail');return}ui.writingStep++;ui.error='';render();if(ui.writingStep===3)runWrite();break;
case 'write-confirm':closeModal();ui.writingStep=3;render();runWrite();break;
case 'write-fail':ui.writingStep=0;ui.hardwareConnected=false;ui.error='Connection lost. Reconnect the speaker and check its state before trying again.';render();break;
case 'checkout':beginCheckout(d.order||'Card print');break;
case 'checkout-info':notify('This is a checkout simulation. No personal or payment information is collected.');break;
case 'order-success':case 'order-cancel':case 'order-pending':ui.orderStatus=name.split('-')[1];go('order-result');break;
case 'order-recheck':ui.orderStatus='success';render();break;
case 'order-return':go(ui.orderReturn||'detail');break;
case 'close-modal':closeModal();break;
case 'guide':openGuide();break;
case 'reset-confirm':openModal('Reset demo data?','<p>This clears creations and drafts saved in this browser and restores the sample cards.</p>',primary('Reset demo','reset-demo')+secondary('Keep my work','close-modal'));break;
case 'reset-demo':localStorage.removeItem(KEY);sessionStorage.removeItem(KEY+'-view');location.href=location.pathname+'#/home';location.reload();break;
default:go(name);
}}
function runWrite(){let n=0;const interval=setInterval(()=>{if(route!=='write'||ui.writingStep!==3){clearInterval(interval);return}n+=10;if($('#write-progress'))$('#write-progress').value=n;if($('#write-percent'))$('#write-percent').textContent=n+'%';if(n>=100){clearInterval(interval);ui.writingStep=4;render()}},180)}
function openGuide(){openModal('Create V1',`<p>先从首页进入 Create，六个入口都可点击走查。</p><p>作品和草稿保存在当前浏览器。可以上传自己的图片、真实录音，或用演示录音快速走完流程。</p><p>声音列表复用同一段 Paper Zen 演示音乐；图片先沿用四款色彩习作。扫码与分享链接仅在本浏览器验证，付款、音箱连接与写卡均为模拟。</p><p>缺图清单与下一步图片计划在页面外侧的「预览图清单」。礼物动画和界面动效已加入；可在礼物预览中暂停、重播或减少动态效果。</p>`,secondary('Reset demo data','reset-confirm')+primary('Continue','close-modal'))}
app.addEventListener('input',e=>{const n=e.target.name;if(!n)return;if(n.startsWith('card.')){card[n.slice(5)]=e.target.value;saveDraft();syncCardValidation()}else if(n.startsWith('album.')){album[n.slice(6)]=e.target.value;persist()}else if(n.startsWith('gift.')){gift[n.slice(5)]=e.target.value;persist()}else if(n==='voice-volume'||n==='sound-volume'){const key=n==='voice-volume'?'voiceVolume':'soundVolume';soundState()[key]=+e.target.value;player.volume(n==='voice-volume'?'voice':'sound',+e.target.value);e.target.previousElementSibling.textContent=e.target.value+'%';persist()}else if(n==='sound-search'||n==='bazaar-search'){const caret=e.target.selectionStart;ui[n==='sound-search'?'soundSearch':'search']=e.target.value;render();const target=app.querySelector(`[name="${n}"]`);target.focus();target.setSelectionRange(caret,caret)}else if(n.startsWith('crop-')){ui[{'crop-scale':'cropScale','crop-x':'cropX','crop-y':'cropY'}[n]]=+e.target.value;updateCrop()}});
app.addEventListener('change',e=>{if(e.target.id==='photo-input')loadPhoto(e.target.files[0]);if(e.target.name==='demo-connected')ui.hardwareConnected=e.target.checked;if(e.target.name==='demo-card')ui.hardwareCard=e.target.checked;if(e.target.name==='demo-used-card')ui.usedCard=e.target.checked});
document.addEventListener('input',e=>{if(e.target.matches('[data-audio-progress]'))player.seek(+e.target.value)});
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-go]');if(!b||b.disabled)return;motionIntent(b.dataset.action||b.dataset.go,b.dataset.action==='back'||b.dataset.action==='gift-preview-back');if(b.dataset.go){if(b.dataset.go==='library'){ui.libraryStatus='completed';ui.libraryType='card'}go(b.dataset.go)}else if(b.dataset.action){Promise.resolve(action(b.dataset.action,b.dataset)).catch(error=>{console.error(error);notify('Something did not finish. Your work is kept. Please try again.')})}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='card-form')generateCard().catch(error=>{console.error(error);notify('Your card could not be created. Your draft is kept. Please try again.')})});modal.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='custom-memory-form')saveCustomMemory()});modal.addEventListener('cancel',()=>player.pause());modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
$('#review-menu').addEventListener('click',openGuide);
let dragId;app.addEventListener('dragstart',e=>{dragId=e.target.closest('[data-drag-id]')?.dataset.dragId;e.dataTransfer?.setData('text/plain',dragId||'')});app.addEventListener('dragover',e=>{if(e.target.closest('[data-drag-id]'))e.preventDefault()});app.addEventListener('drop',e=>{const id=e.target.closest('[data-drag-id]')?.dataset.dragId;if(id&&dragId&&id!==dragId){e.preventDefault();const from=album.cardIds.indexOf(dragId),to=album.cardIds.indexOf(id);if(from<0||to<0)return;album.cardIds.splice(from,1);album.cardIds.splice(to,0,dragId);persist();render()}});
let touchStart;app.addEventListener('touchstart',e=>{touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY,el:e.target.closest('[data-swipe],.sound-tray')}});app.addEventListener('touchend',e=>{if(!touchStart?.el)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(touchStart.el.dataset.swipe&&Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){motionIntent(touchStart.el.dataset.swipe==='template'?'next-template':'speaker-next');action(touchStart.el.dataset.swipe==='template'?(dx<0?'next-template':'prev-template'):(dx<0?'speaker-next':'speaker-prev'));}else if(touchStart.el.classList.contains('sound-tray')&&Math.abs(dy)>45){motionIntent('expand-sound');ui.soundExpanded=dy<0;render()}touchStart=null});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(2).split('?')[0]||'home';if(route!==next){player.pause();motionIntent('browser-navigation',true);route=next;render()}});window.addEventListener('pagehide',()=>{giftCinema?.destroy();player.pause();stopRecordingTracks()});
if(['detail','album-detail'].includes(route)){const c=currentItem(),s=c.type==='album'&&c.intro&&typeof c.intro==='object'?c.intro:c;player.configure({voice:s.recording,background:!!s.sound||c.type==='album',voiceVolume:s.voiceVolume,soundVolume:s.soundVolume});}
installMotion(app);
$('#status-icons').innerHTML=icon('signal')+icon('wifi')+icon('battery-full');render();
const modelContext=document.modelContext;if(modelContext?.registerTool){const abort=new AbortController();const result=()=>({page:route,card:{name:card.name,photo:!!card.photo,recording:!!card.recording,sound:card.sound,mixed:card.mixed},creations:db.cards.length,albums:db.albums.length});for(const tool of [{name:'read_create_demo_state',title:'Read Create demo state',description:'Read the current visible demo route and creation progress. Does not modify anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>result()},{name:'navigate_create_demo',title:'Open a Create section',description:'Navigate to an existing Create demo section. This does not create or publish a work.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['home','create','memory','library','explore']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||!['home','create','memory','library','explore'].includes(input.section))throw new Error('Unknown section');go(input.section);await new Promise(requestAnimationFrame);return result()}}])Promise.resolve(modelContext.registerTool(tool,{signal:abort.signal})).catch(()=>{});window.addEventListener('pagehide',()=>abort.abort(),{once:true})}

function memoryThemes(){return [...themes.map((t,i)=>({...t,id:'theme-'+i})),...db.customThemes.map(t=>({...t,custom:true}))]}
function selectedMemoryTheme(){return memoryThemes()[ui.theme]||memoryThemes()[0]}
function memorySubthemes(theme){return [...new Set([...(theme.items||[]),...(db.customSubthemes[theme.id]||[])])]}
function customOption(title,sub,action){return `<button class="option-row custom-option" data-action="${action}"><span><strong>${esc(title)}</strong><small>${esc(sub)}</small></span>${icon('plus')}</button>`}
function openCustomMemory(kind){ui.customMemoryKind=kind;const isTheme=kind==='theme';openModal(isTheme?'Create a theme':'Your own moment',`<form id="custom-memory-form" class="custom-form"><label class="field"><span>${isTheme?'Theme name':'Moment name'}</span><input id="custom-memory-name" name="custom-memory-name" maxlength="${isTheme?48:80}" autocomplete="off" placeholder="${isTheme?'e.g. Our little rituals':'e.g. Sunday tea with Mum'}" aria-describedby="custom-memory-error"></label><p id="custom-memory-error" role="alert"></p><button type="submit" class="primary">${isTheme?'Create theme':'Use this moment'}</button></form>`,secondary('Cancel','close-modal'))}
function saveCustomMemory(){const input=$('#custom-memory-name');if(!input)return;const value=input.value.trim().replace(/\s+/g,' ');const error=$('#custom-memory-error');if(!value){error.className='inline-error';error.textContent='Enter a name to continue.';input.setAttribute('aria-invalid','true');input.focus();return}if(ui.customMemoryKind==='theme'){const all=memoryThemes();let index=all.findIndex(t=>t.title.toLocaleLowerCase()===value.toLocaleLowerCase());if(index<0){db.customThemes.push({id:uid('theme'),title:value,description:'A memory that is yours to name.',items:[]});index=memoryThemes().length-1}ui.theme=index;persist();closeModal();go('subtheme');}else{const theme=selectedMemoryTheme(),existing=memorySubthemes(theme).find(t=>t.toLocaleLowerCase()===value.toLocaleLowerCase());if(!existing){db.customSubthemes[theme.id] ||= [];db.customSubthemes[theme.id].push(value)}persist();closeModal();beginCard('memory',theme.title,existing||value)}}
function openArrangeMenu(id){const item=albumCards().find(c=>c.id===id),i=album.cardIds.indexOf(id);if(!item)return;openModal(item.name,`<div class="menu-list">${row('Move earlier','','move-card',{id,dir:-1},i===0)}${row('Move later','','move-card',{id,dir:1},i===album.cardIds.length-1)}${row('Remove from album','Keeps the original in My Creativity','remove-album-card',{id})}</div>`,secondary('Done','close-modal'))}
function mountGift(){const visual=gift.blessing||gift.items[0];const track=visual?.type==='album'?(visual.intro&&typeof visual.intro==='object'?visual.intro:visual.snapshots?.[0]):visual;player.configure({voice:track?.recording,limit:track?.recordingDuration||null,voiceVolume:track?.voiceVolume??75,soundVolume:track?.soundVolume??35});giftCinema=mountGiftPreview(app.querySelector('.gift-cinema'),{icon,icons,prime:()=>player.prime(),audio:{play:()=>player.playing?Promise.resolve():player.toggle(),pause:()=>player.pause()}})}
